CREATE TABLE room_invite (id UUID PRIMARY KEY DEFAULT uuid_v7(),room_id UUID NOT NULL,issuer_id UUID NOT NULL,invitee_id UUID NOT NULL,role VARCHAR(24) NOT NULL DEFAULT 'MEMBER',idempotency_key VARCHAR(256) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'PENDING',expires_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,CHECK(role IN ('MODERATOR','MEMBER','GUEST')),CHECK(status IN ('PENDING','ACCEPTED','DECLINED','EXPIRED','REVOKED')),FOREIGN KEY(room_id) REFERENCES room(id)); CREATE UNIQUE INDEX uq_room_invite_idempotency ON room_invite(issuer_id,idempotency_key); CREATE INDEX idx_room_invitee ON room_invite(invitee_id,created_at DESC);
